 figures=''.join(f'<figure><figcaption>{esc(label)}</figcaption><a href="{esc(v["url"])}" target="_blank"><img src="{esc(v["url"])}" width="1000" height="1100" alt="{esc(row["sku"])} {esc(label)}"></a><details><summary>Image fingerprint</summary><code>{v["sha256"]}</code></details></figure>' for v,label in views)
