 parts.append(f'<article data-kind="{esc(row["classification"])}" data-sku="{esc(row["sku"])}"><div class="eyebrow">{i+1:02} / 38 · {esc(row["classification"])}</div><h2>{row["capacityMl"]} mL · {esc(row["color"])} · {esc(row["capColor"])}</h2><p class="sku">{esc(row["sku"])}</p><div class="views" style="--cols:{len(views)}">{figures}</div><p class="metric">Body alignment: {row["pairCheck"]["bodyMeanError"]:.2f} / 255 · limit 12. Same 1000 × 1100 canvas and zoom.</p><details><summary>Source and preparation notes</summary><p>{esc(row["itemName"])}</p><ul>{notes}</ul><code>{row["binding"]}</code></details>{"<p class=source-note>Source decision: retain the approved original legacy front. The ledger currently requires a master source for this view.</p>" if source_pending else "<p class=pass>Master sources verified. Original source approval remains saved.</p>"}</article>')
